using System.Windows;using OncaPDV.Domain;namespace OncaPDV.Desktop;public partial class PaymentMethodChangeWindow:Window{public PaymentMethod Method{get;private set;}public string Reason=>ReasonBox.Text.Trim();public PaymentMethodChangeWindow(){InitializeComponent();}private void Ok_Click(object s,RoutedEventArgs e){if(string.IsNullOrWhiteSpace(Reason)){MessageBox.Show("Informe o motivo.");return;}Method=MethodBox.SelectedIndex switch{1=>PaymentMethod.Pix,2=>PaymentMethod.Debit,3=>PaymentMethod.Credit,4=>PaymentMethod.StoreCredit,_=>PaymentMethod.Cash};DialogResult=true;}}
